    h, w = len(grid), len(grid[0])
    solid_rows = {r: row[0] for r, row in enumerate(grid)
                  if row[0] != 0 and all(v == row[0] for v in row)}
    if len(solid_rows) >= 2:
        period = len(solid_rows)
        phases = {r % period: color for r, color in solid_rows.items()}
        return [[phases[r % period] for _ in range(w)] for r in range(h)]

    diagonals = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in diagonals and diagonals[d] != color:
                    raise ValueError("input does not contain uniform diagonals")
                diagonals[d] = color
    period = len(diagonals)
    phases = {d % period: color for d, color in diagonals.items()}
    return [[phases[(c-r) % period] for c in range(w)] for r in range(h)]
